#### Local best practices

For basic usage, create a `best_practices.md` file in your repository's root directory containing a list of best practices, coding standards, and guidelines specific to your repository.

The AI model will use this `best_practices.md` file as a reference, and in case the PR code violates any of the guidelines, it will create additional suggestions, with a dedicated label: `Organization best practice`.

### Combining 'extra instructions' and 'best practices'

The `extra instructions` configuration is more related to the `improve` tool prompt. It can be used, for example, to avoid specific suggestions ("Don't suggest to add try-except block", "Ignore changes in toml files", ...) or to emphasize specific aspects or formats ("Answer in Japanese", "Give only short suggestions", ...)

In contrast, the `best_practices.md` file is a general guideline for the way code should be written in the repo.

def run_evaluation(
    protocols: Optional[List[MatchingProtocol]] = None,
    include_candidate_cohort2: bool = False,
    output_dir: Path = OUTPUT_DIR,
) -> Dict[str, pd.DataFrame]:
    """Run full evaluation matrix across all available configurations and protocols."""
    output_dir.mkdir(parents=True, exist_ok=True)
    target_protocols = protocols or [
        MatchingProtocol.M1_STRICT,
        MatchingProtocol.M2_TOLERANT,
        MatchingProtocol.M3_SEMANTIC,
    ]

    cohort_label = "Cohort1_Confirmed" if not include_candidate_cohort2 else "Cohort1_and_Cohort2"
    logger.info(f"Loading Ground Truth ({cohort_label})...")
    gt_by_pr = load_ground_truth(include_candidate_cohort2=include_candidate_cohort2)
    logger.info(f"Loaded ground truth for {len(gt_by_pr)} PRs.")

    protocol_dfs: Dict[str, pd.DataFrame] = {}

    for proto in target_protocols:
        logger.info(f"\n--- Evaluating Protocol: {proto.value} ---")
        rows = []
        per_config_pr_results: Dict[str, List[MatchingResult]] = {}

        for cfg in ALL_CONFIGS:
            preds_by_pr = load_raw_predictions(cfg)
            if not preds_by_pr:
                continue

            summary, pr_res = evaluate_configuration(cfg, gt_by_pr, preds_by_pr, protocol=proto)
            rows.append(summary)
            per_config_pr_results[cfg] = pr_res

        if not rows:
            logger.warning(f"No prediction data found for any configuration under {proto.value}.")
            continue

        df_summary = pd.DataFrame(rows)

        # Compute Wilcoxon signed-rank test comparing E6 against each baseline
        if "E6" in per_config_pr_results:
            e6_prs = {r.pr_id: r.benchmark_apparent_f1 for r in per_config_pr_results["E6"]}
            wilcoxon_results = {}
            for other_cfg, other_res in per_config_pr_results.items():
                if other_cfg == "E6":
                    continue
                other_prs = {r.pr_id: r.benchmark_apparent_f1 for r in other_res}
                common_ids = sorted(set(e6_prs.keys()).intersection(set(other_prs.keys())))
                diffs = [e6_prs[pid] - other_prs[pid] for pid in common_ids]

                # Wilcoxon requires non-zero differences
                non_zeros = [d for d in diffs if d != 0]
                if len(non_zeros) >= 5:
                    stat, p_val = stats.wilcoxon(diffs, zero_method="pratt")
                    wilcoxon_results[other_cfg] = round(p_val, 4)
                else:
                    wilcoxon_results[other_cfg] = "N/A (<5 non-zero diffs)"

            df_summary["wilcoxon_p_vs_E6"] = df_summary["config_id"].map(
                lambda c: wilcoxon_results.get(c, "Baseline") if c != "E6" else "Reference (E6)"
            )

        csv_name = f"metrics_summary_{proto.value.lower()}_{cohort_label.lower()}.csv"
        csv_path = output_dir / csv_name
        df_summary.to_csv(csv_path, index=False)
        protocol_dfs[proto.value] = df_summary

        print(f"\n===== RESULTS SUMMARY [{proto.value}] ({cohort_label}) =====\n")
        print(df_summary.to_string(index=False))

    return protocol_dfs

def extract_files_from_diff(diff_content: str) -> Set[str]:
    """Extract set of normalized modified file paths from a unified diff."""
    files = set()
    for line in diff_content.splitlines():
        if line.startswith("+++ b/") or line.startswith("--- a/"):
            path = line[6:].strip()
            if path and path != "/dev/null":
                files.add(path.replace("\\", "/").lower())
        elif line.startswith("diff --git"):
            parts = line.split()
            if len(parts) >= 4:
                b_path = re.sub(r"^[ab]/", "", parts[3]).strip()
                files.add(b_path.replace("\\", "/").lower())
    return files

def evaluate_rag_retrieval(
    config_id: str = "E6",
    raw_dir: Path = RAW_RESULTS_DIR,
    diffs_dir: Path = DIFFS_DIR,
    manifest_path: Path = MANIFEST_PATH,
    top_ks: Tuple[int, ...] = (1, 3, 5),
) -> Dict[str, Any]:
    """
    Evaluate retrieval quality across all PRs for a given RAG configuration.
    """
    cfg_dir = raw_dir / config_id
    if not cfg_dir.exists():
        logger.warning(f"Raw results directory not found for {config_id}: {cfg_dir}")
        return {}

    # Load diff files map
    pr_diff_files: Dict[str, Set[str]] = {}
    if manifest_path.exists():
        with open(manifest_path, "r", encoding="utf-8") as f:
            reader = csv.DictReader(f)
            for row in reader:
                if row.get("status", "").upper() == "SUCCESS":
                    diff_file = Path(row["diff_file"])
                    pr_id = diff_file.stem
                    if diff_file.exists():
                        content = diff_file.read_text(encoding="utf-8", errors="replace")
                        pr_diff_files[pr_id] = extract_files_from_diff(content)

    reciprocal_ranks = []
    dfor_at_k: Dict[int, List[float]] = {k: [] for k in top_ks}
    ndcg_at_k: Dict[int, List[float]] = {k: [] for k in top_ks}
    total_chunks_retrieved = 0
    prs_with_context = 0

    for json_file in sorted(cfg_dir.glob("*.json")):
        if json_file.name == "execution_manifest.json":
            continue

        pr_id = json_file.stem
        try:
            with open(json_file, "r", encoding="utf-8") as f:
                data = json.load(f)
        except Exception as e:
            logger.error(f"Failed to read {json_file}: {e}")
            continue

        # Look for retrieved RAG chunks in execution_manifest or findings
        retrieved_chunks = []
        exec_manifest = data.get("execution_manifest", {})
        if "rag_context_snippets" in exec_manifest:
            retrieved_chunks = exec_manifest["rag_context_snippets"]
        elif "rag_context" in data:
            retrieved_chunks = data["rag_context"]

        # Also inspect findings for related_context_chunks
        if not retrieved_chunks:
            for finding in data.get("findings", []):
                chunks = finding.get("related_context_chunks", [])
                if chunks:
                    retrieved_chunks.extend(chunks)

        if not retrieved_chunks:
            continue

        prs_with_context += 1
        total_chunks_retrieved += len(retrieved_chunks)

        # PR modified files
        modified_files = pr_diff_files.get(pr_id, set())

        # Determine binary relevance: does chunk file overlap with PR modified files?
        relevance_vector = []
        first_rel_rank = 0

        for rank_idx, chunk in enumerate(retrieved_chunks, 1):
            chunk_file = ""
            if isinstance(chunk, dict):
                chunk_file = chunk.get("file_path", "") or chunk.get("file", "")
            elif isinstance(chunk, str):
                # Attempt to extract file path header e.g. "File: src/models.py"
                m = re.search(r"File:\s*([^\s\n]+)", chunk)
                if m:
                    chunk_file = m.group(1)

            norm_chunk_file = chunk_file.strip().replace("\\", "/").lower()
            is_relevant = 0.0

            if norm_chunk_file and any(
                norm_chunk_file in mf or mf in norm_chunk_file for mf in modified_files
            ):
                is_relevant = 1.0

            relevance_vector.append(is_relevant)

            if is_relevant > 0 and first_rel_rank == 0:
                first_rel_rank = rank_idx

        # Compute MRR
        reciprocal_ranks.append(1.0 / first_rel_rank if first_rel_rank > 0 else 0.0)

        # Compute DFOR@K and nDCG@K
        for k in top_ks:
            top_k_rel = relevance_vector[:k]
            overlap_count = sum(top_k_rel)
            dfor = (overlap_count / min(k, len(top_k_rel))) if top_k_rel else 0.0
            dfor_at_k[k].append(dfor)
            ndcg = compute_ndcg_at_k(relevance_vector, k)
            ndcg_at_k[k].append(ndcg)

    mrr = float(np.mean(reciprocal_ranks)) if reciprocal_ranks else 0.0
    summary = {
        "config_id": config_id,
        "prs_evaluated": prs_with_context,
        "total_chunks_evaluated": total_chunks_retrieved,
        "mrr": round(mrr, 4),
    }

    for k in top_ks:
        summary[f"dfor@{k}"] = round(float(np.mean(dfor_at_k[k])), 4) if dfor_at_k[k] else 0.0
        summary[f"ndcg@{k}"] = round(float(np.mean(ndcg_at_k[k])), 4) if ndcg_at_k[k] else 0.0

    return summary

def normalize_file_path(path: str) -> str:
    """Normalize file path for cross-platform comparison."""
    if not path:
        return ""
    p = path.strip().replace("\\", "/").lower()
    p = re.sub(r"^[ab]/", "", p)  # Strip git a/ or b/ prefixes
    return p.lstrip("/")

def tokenize_text(text: str) -> Set[str]:
    """Tokenize text into lowercase alphanumeric words."""
    if not text:
        return set()
    return set(re.findall(r"[a-z0-9_]{2,}", text.lower()))

def compute_line_distance(
    pred_start: int,
    pred_end: int,
    gt_line: int,
    granularity: Any = FindingGranularity.STATEMENT,
) -> int:
    """
    Compute line distance taking into account localization granularity.
    - If STATEMENT: |pred_start - gt_line|
    - If HUNK_SPAN: minimum distance to span [pred_start, pred_end]
      (i.e. 0 if gt_line falls inside span, else min(|gt - start|, |gt - end|))
    """
    gran_val = granularity.value if hasattr(granularity, "value") else str(granularity)
    if gran_val == FindingGranularity.HUNK_SPAN.value:
        if pred_start <= gt_line <= pred_end:
            return 0
        return min(abs(gt_line - pred_start), abs(gt_line - pred_end))

    # Default statement line-specific
    return abs(pred_start - gt_line)

def sample_candidates(
    fps: List[Dict[str, Any]],
    n_samples: int,
    seed: int = 42,
) -> List[Dict[str, Any]]:
    """Sample candidates using reproducible seeded pseudo-random selection with stratification."""
    if not fps:
        return []

    if len(fps) <= n_samples:
        return list(fps)

    rng = np.random.default_rng(seed)
    df = pd.DataFrame(fps)

    # Attempt stratified sampling by category and severity
    if "category" in df.columns and "severity" in df.columns:
        groups = df.groupby(["category", "severity"], group_keys=False)
        # Proportionate allocation
        weights = df.groupby(["category", "severity"])["finding_id"].transform("count")
        prob = weights / weights.sum()
        chosen_indices = rng.choice(len(df), size=n_samples, replace=False, p=prob.values / prob.values.sum())
    else:
        chosen_indices = rng.choice(len(df), size=n_samples, replace=False)

    sampled_df = df.iloc[chosen_indices].copy()
    return sampled_df.to_dict(orient="records")

