def _next_page_url(headers: dict) -> str:
    link = headers.get("Link", "")
    if not link:
        return ""
    for part in link.split(","):
        match = re.search(r'<([^>]+)>\s*;\s*rel="next"', part.strip())
        if match:
            return match.group(1)
    return ""

